mapper.select:
SELECT
t_help_doc.* ,
t_help_doc_catalog.name as helpDocCatalogName
FROM t_help_doc
left join t_help_doc_catalog on t_help_doc_catalog.help_doc_catalog_id = t_help_doc.help_doc_catalog_id


        AND t_help_doc.help_doc_catalog_id = #{query.helpDocCatalogId}


        AND ( t_help_doc.title ILIKE CONCAT('%', #{query.keywords}, '%')
        OR t_help_doc.author ILIKE CONCAT('%', #{query.keywords}, '%')
        )


        AND TO_CHAR(t_help_doc.create_time, 'YYYY-MM-DD') >= #{query.createTimeBegin}


        AND TO_CHAR(t_help_doc.create_time, 'YYYY-MM-DD') <= #{query.createTimeEnd}



    ORDER BY t_help_doc.sort ASC, t_help_doc.create_time DESC

mapper.update:
update t_help_doc
set page_view_count = page_view_count + #{pageViewCountIncrease},
    user_view_count = user_view_count + #{userViewCountIncrease}
where help_doc_id = #{helpDocId}

mapper.select:
select count(*)
from t_help_doc_view_record
where help_doc_id = #{helpDocId}
  and user_id = #{userId}

mapper.update:
update t_help_doc_view_record
set page_view_count = page_view_count + 1,
    last_ip         = #{ip},
    last_user_agent = #{userAgent}
where help_doc_id = #{helpDocId}
  and user_id = #{userId}

mapper.select:
select * from t_help_doc_view_record where help_doc_id = #{queryForm.helpDocId}
AND ( user_name ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR first_ip ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR first_user_agent ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR last_ip ILIKE CONCAT('%', #{queryForm.keywords}, '%') OR last_user_agent ILIKE CONCAT('%', #{queryForm.keywords}, '%') )
and user_id = #{queryForm.userId}
order by update_time desc,create_time desc
